1	import { scoreArmy, type Card } from "./sphinx-score.js";
2	
3	const readAllText = async (stream: NodeJS.ReadStream): Promise<string> => {
4	  let text = "";
5	  for await (const chunk of stream) text += chunk;
6	  return text;
7	};
8	
9	const scoreArmyRequest = (requestJson: string): string => {
10	  const { army } = JSON.parse(requestJson) as { army: Card[] };
11	  return JSON.stringify({ score: scoreArmy(army) });
12	};
13	
14	const main = async (): Promise<void> => {
15	  const requestJson = await readAllText(process.stdin);
16	  process.stdout.write(scoreArmyRequest(requestJson));
17	};
18	
19	await main();
