1	import { describe, it, expect } from "vitest";
2	import { spawn } from "node:child_process";
3	
4	const runCli = (input: string): Promise<string> =>
5	  new Promise((resolve, reject) => {
6	    const child = spawn("pnpm", ["exec", "tsx", "src/cli.ts"], {
7	      cwd: process.cwd(),
8	    });
9	
10	    let stdout = "";
11	    let stderr = "";
12	    child.stdout.on("data", (chunk) => (stdout += chunk));
13	    child.stderr.on("data", (chunk) => (stderr += chunk));
14	    child.on("error", reject);
15	    child.on("close", (code) =>
16	      code === 0
17	        ? resolve(stdout)
18	        : reject(new Error(`cli exited with ${code}: ${stderr}`)),
19	    );
20	
21	    child.stdin.end(input);
22	  });
23	
24	describe("Sphinx scoring CLI", () => {
25	  it("reads an army from stdin and writes the score to stdout", async () => {
26	    const stdout = await runCli(
27	      JSON.stringify({
28	        army: [
29	          { monster: "sphinx" },
30	          { monster: "undead-warrior", rank: 2 },
31	          { monster: "hydra" },
32	        ],
33	      }),
34	    );
35	
36	    expect(JSON.parse(stdout)).toEqual({ score: 2 });
37	  });
38	});
